#!/usr/bin/env bashset -eif [ -n "${DB_HOST}" ]; then  echo "Waiting for Postgres at ${DB_HOST}:${DB_PORT:-5432}..."  until nc -z "${DB_HOST}" "${DB_PORT:-5432}"; do    sleep 1  donefiif [ "$1" = "web" ]; then  python manage.py migrate --noinput  python manage.py collectstatic --noinputficase "$1" in  web)    exec gunicorn mysite.wsgi:application \      --bind 0.0.0.0:8000 \      --workers ${GUNICORN_WORKERS:-3} \      --timeout ${GUNICORN_TIMEOUT:-60} \      --access-logfile - --error-logfile -    ;;  worker)    exec celery -A mysite worker -l INFO --concurrency=${CELERY_CONCURRENCY:-2}    ;;  beat)    exec celery -A mysite beat -l INFO    ;;  *)    exec "$@"    ;;esac